sp_instance.widget_parameters:
{
	"html": {
		"value": "<style>
    .welcome-banner-container {
        background: linear-gradient(135deg, #0055a5 0%, #2a75c2 100%); /* Blue gradient */
        border-radius: 12px;
        padding: 40px 30px;
        color: white;
        text-align: center;
        font-family: 'Inter', Arial, sans-serif;
        box-shadow: 0 8px 16px rgba(0,0,0,0.1);
    }
    .welcome-banner-container h1 {
        font-size: 2.5em;
        font-weight: 600;
        margin: 0 0 10px 0;
    }
    .welcome-banner-container p {
        font-size: 1.2em;
        opacity: 0.9;
        margin-bottom: 30px;
    }
    .search-bar-container {
        max-width: 600px;
        margin: 0 auto 30px auto;
        background: white;
        border-radius: 50px;
        padding: 8px;
        display: flex;
        align-items: center;
    }
    .search-bar-container input {
        border: none;
        outline: none;
        width: 100%;
        padding: 10px 20px;
        font-size: 1em;
        background: transparent;
        color: #333;
    }
    .quick-links-container {
        display: flex;
        justify-content: center;
        gap: 20px;
        flex-wrap: wrap; /* Allows links to wrap on smaller screens */
    }
    .quick-link {
        color: white;
        text-decoration: none;
        background: rgba(255, 255, 255, 0.15);
        padding: 12px 20px;
        border-radius: 50px;
        display: flex;
        align-items: center;
        gap: 8px;
        transition: background 0.2s ease;
    }
    .quick-link:hover {
        background: rgba(255, 255, 255, 0.3);
    }
    .quick-link svg {
        width: 20px;
        height: 20px;
    }
</style>
<div class="welcome-banner-container">
<h1>Welcome, Buddy!</h1>
<p>How can we help you today?</p>
<div class="search-bar-container"><input type="text" placeholder="Search the Knowledge Base or Service Catalog..."></div>
<div class="quick-links-container"><a class="quick-link" href="/pm?id=sc_home"> Request Something </a> <a class="quick-link" href="/pm?id=kb_view2"> Find an Answer </a> <a class="quick-link" href="/pm?id=requests"> Check My Tickets </a></div>
</div>",
